const message = $json.body.message || $json.message || {};
const toolCalls = message.toolCalls || [];

if (!toolCalls || toolCalls.length === 0) {
  return [{ json: { error: 'No tool calls found', toolCallId: 'unknown' } }];
}

const primaryCall = toolCalls[0];
const functionName = primaryCall.function.name;
let args = {};
try {
  args = typeof primaryCall.function.arguments === 'string' 
    ? JSON.parse(primaryCall.function.arguments) 
    : primaryCall.function.arguments;
} catch (e) {
  args = {};
}

return [{
  json: {
    toolCallId: primaryCall.id,
    functionName: functionName,
    arguments: args,
    callId: message.call ? message.call.id : 'local-call-mock'
  }
}];

const args = $json.arguments;
const targetDate = args.target_date || new Date().toISOString().split('T')[0];
const service = args.service_name || 'Haircut';
const stylist = args.preferred_stylist || 'any';

// Simulate database / Google Calendar slot calculation
const morningSlots = ['10:00 AM', '11:15 AM'];
const afternoonSlots = ['2:00 PM', '3:30 PM', '4:45 PM'];

let responseText = `On ${targetDate}, for a ${service}`;
if (stylist !== 'any') {
  responseText += ` with ${stylist}`;
}
responseText += `, we have openings at 11:15 AM, 2:00 PM, and 3:30 PM. Which time works best for you?`;

return [{
  json: {
    results: [{
      toolCallId: $json.toolCallId,
      result: responseText
    }]
  }
}];

const args = $json.arguments;
const bookingId = 'LUXE-' + Math.floor(1000 + Math.random() * 9000);
const name = args.caller_name || 'Valued Guest';
const phone = args.caller_phone || 'Unverified';
const service = args.service_name || 'Haircut';
const dt = args.appointment_datetime || '2026-10-31T14:00:00';
const stylist = args.stylist_name || 'Elena';

const formattedTime = new Date(dt).toLocaleString('en-US', {
  weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'
});

const resultText = `Booking confirmed! Appointment ID is ${bookingId} for ${name} for a ${service} with ${stylist} on ${formattedTime}. A confirmation SMS has been sent to ${phone}.`;

return [{
  json: {
    bookingId,
    callerName: name,
    callerPhone: phone,
    results: [{
      toolCallId: $json.toolCallId,
      result: resultText
    }]
  }
}];

const args = $json.arguments;
const phone = args.caller_phone || '';

const resultText = `I found an active reservation for ${phone}: Balayage with Elena on Saturday at 2:00 PM (Booking Ref: LUXE-8421). Would you like to reschedule or cancel this?`;

return [{
  json: {
    results: [{
      toolCallId: $json.toolCallId,
      result: resultText
    }]
  }
}];

const args = $json.arguments;
const phone = args.caller_phone || '';
const bookingId = args.booking_id || 'your booking';

const resultText = `Your appointment (${bookingId}) has been successfully canceled. No cancellation fee was charged. We hope to see you again soon at Luxe Salon!`;

return [{
  json: {
    results: [{
      toolCallId: $json.toolCallId,
      result: resultText
    }]
  }
}];

const payload = $json.body || {};
const message = payload.message || {};

const summary = message.summary || 'No summary available';
const transcript = message.transcript || 'No transcript';
const recordingUrl = message.recordingUrl || '';
const durationSeconds = message.durationSeconds || 0;
const customerPhone = message.customer ? message.customer.number : 'Unknown';

return [{
  json: {
    summary,
    customerPhone,
    durationSeconds,
    recordingUrl,
    transcriptSnippet: transcript.slice(0, 300) + '...'
  }
}];
